begin;
create or replace function platform.notification_gateway(p_operation text,p_args jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare result jsonb;delivery_id uuid;status_value text;begin if coalesce(auth.jwt()->>'role','')<>'service_role' then raise exception 'PLATFORM_NOTIFICATION_BACKEND_REQUIRED' using errcode='42501';end if;if p_operation='enqueue' then perform platform_private.require_exact_jsonb_keys(p_args,array['eventType','moduleKey','resourceType','resourceId','title','body','targetUrl','dedupeKey']);return platform_private.enqueue_notification(p_args->>'eventType',p_args->>'moduleKey',p_args->>'resourceType',p_args->>'resourceId',p_args->>'title',p_args->>'body',p_args->>'targetUrl',p_args->>'dedupeKey');elsif p_operation='pending' then perform platform_private.require_exact_jsonb_keys(p_args,array['limit']);select coalesce(jsonb_agg(jsonb_build_object('deliveryId',d.id,'endpoint',s.endpoint,'p256dh',s.p256dh,'auth',s.auth_secret,'title',e.title,'body',e.body,'targetUrl',e.target_url,'eventType',e.event_type) order by e.created_at,d.id),'[]'::jsonb) into result from (select * from platform.notification_deliveries where status in('pending','failed') and attempt_count<5 order by notification_event_id,id limit least(greatest((p_args->>'limit')::int,1),100)) d join platform.notification_push_subscriptions s on s.id=d.subscription_id and s.active join platform.notification_events e on e.id=d.notification_event_id;return result;elsif p_operation='mark' then perform platform_private.require_exact_jsonb_keys(p_args,array['deliveryId','status','errorCode']);delivery_id:=(p_args->>'deliveryId')::uuid;status_value:=p_args->>'status';if status_value not in('sent','failed','expired') then raise exception 'PLATFORM_NOTIFICATION_DELIVERY_STATUS_INVALID' using errcode='22023';end if;update platform.notification_deliveries set status=status_value,attempt_count=attempt_count+1,last_attempt_at=statement_timestamp(),last_error_code=nullif(p_args->>'errorCode',''),delivered_at=case when status_value='sent' then statement_timestamp() else delivered_at end where id=delivery_id;if not found then raise exception 'PLATFORM_NOTIFICATION_DELIVERY_NOT_FOUND' using errcode='P0002';end if;return jsonb_build_object('deliveryId',delivery_id,'status',status_value);else raise exception 'PLATFORM_NOTIFICATION_OPERATION_NOT_ALLOWED' using errcode='42501';end if;end$$;
revoke all on function platform.notification_gateway(text,jsonb) from public,anon,authenticated;grant execute on function platform.notification_gateway(text,jsonb) to service_role;
commit;
